     1|/**
     2| * IVX Owner Authorization Endpoint
     3| *
     4| * Architecture: Supabase answers WHO; IVX answers WHAT.
     5| * This endpoint receives a valid Supabase access token in the Authorization header,
     6| * validates it with Supabase Auth, and returns the IVX owner authorization result.
     7| * It never accepts passwords or creates sessions.
     8| */
     9|
    10|import { createClient } from '@supabase/supabase-js';
    11|
    12|const DEPLOYMENT_MARKER = 'ivx-owner-auth-v1';
    13|const ADMIN_ROLES = ['owner', 'admin', 'ceo', 'staff', 'manager', 'analyst', 'support'] as const;
    14|const ROLE_ALIASES: Record<string, string> = {
    15|  super_admin: 'admin',
    16|  superadmin: 'admin',
    17|  administrator: 'admin',
    18|  admin_user: 'admin',
    19|  adminuser: 'admin',
    20|  owner_admin: 'owner',
    21|  owneradmin: 'owner',
    22|  chief_executive_officer: 'ceo',
    23|  chiefexecutiveofficer: 'ceo',
    24|  staff_member: 'staff',
    25|  staffmember: 'staff',
    26|  team_manager: 'manager',
    27|  teammanager: 'manager',
    28|  support_staff: 'support',
    29|  supportstaff: 'support',
    30|  support_agent: 'support',
    31|  supportagent: 'support',
    32|  customer_support: 'support',
    33|  customersupport: 'support',
    34|};
    35|
    36|function canonicalizeRole(role: string | null | undefined): string {
    37|  return role?.trim().toLowerCase().replace(/[\s-]+/g, '_') ?? '';
    38|}
    39|
    40|function normalizeRole(role: string | null | undefined): string {
    41|  const normalized = canonicalizeRole(role);
    42|  if (!normalized) return 'investor';
    43|  const aliased = ROLE_ALIASES[normalized] ?? normalized;
    44|  if (ADMIN_ROLES.includes(aliased as typeof ADMIN_ROLES[number])) return aliased;
    45|  return 'investor';
    46|}
    47|
    48|function isAdminRole(role: string | null | undefined): boolean {
    49|  return normalizeRole(role) !== 'investor';
    50|}
    51|
    52|type OwnerAuthorizationResult = {
    53|  success: true;
    54|  authorized: true;
    55|  userId: string;
    56|  email: string;
    57|  role: string;
    58|  roleSource: 'profiles' | 'rpc_verify_admin_access' | 'email_not_owner';
    59|  expiresAt: number;
    60|  deploymentMarker: string;
    61|} | {
    62|  success: false;
    63|  authorized: false;
    64|  reason: 'missing_token' | 'invalid_token' | 'token_expired' | 'supabase_unavailable' | 'not_owner' | 'backend_error';
    65|  message: string;
    66|  deploymentMarker: string;
    67|};
    68|
    69|function jsonResponse(data: unknown, status = 200): Response {
    70|  return new Response(JSON.stringify(data), {
    71|    status,
    72|    headers: {
    73|      'Content-Type': 'application/json',
    74|      'Access-Control-Allow-Origin': 'https://ivxholding.com',
    75|      'Access-Control-Allow-Headers': 'Content-Type, Authorization',
    76|    },
    77|  });
    78|}
    79|
    80|function getSupabaseConfig(): { url: string; anonKey: string } | null {
    81|  const url = process.env.SUPABASE_URL || process.env.EXPO_PUBLIC_SUPABASE_URL || '';
    82|  const anonKey = process.env.SUPABASE_ANON_KEY || process.env.EXPO_PUBLIC_SUPABASE_ANON_KEY || '';
    83|  if (!url || !anonKey) return null;
    84|  return { url, anonKey };
    85|}
    86|
    87|export async function handleOwnerAuthorize(request: Request): Promise<Response> {
    88|  const traceId = request.headers.get('x-ivx-trace-id') || `owner-auth-${Date.now()}`;
    89|  const startedAt = Date.now();
    90|  const token = request.headers.get('Authorization')?.match(/^Bearer\s+(.+)$/i)?.[1]?.trim();
    91|
    92|  if (!token) {
    93|    return jsonResponse({
    94|      success: false,
    95|      authorized: false,
    96|      reason: 'missing_token',
    97|      message: 'Authorization token is required.',
    98|      deploymentMarker: DEPLOYMENT_MARKER,
    99|    }, 401);
   100|  }
   101|
   102|  const config = getSupabaseConfig();
   103|  if (!config) {
   104|    console.error(`[OwnerAuth] ${traceId} Supabase not configured`);
   105|    return jsonResponse({
   106|      success: false,
   107|      authorized: false,
   108|      reason: 'backend_error',
   109|      message: 'IVX authorization service is not configured.',
   110|      deploymentMarker: DEPLOYMENT_MARKER,
   111|    }, 500);
   112|  }
   113|
   114|  try {
   115|    const client = createClient(config.url, config.anonKey, {
   116|      auth: { persistSession: false, autoRefreshToken: false },
   117|    });
   118|
   119|    const { data: userData, error: userError } = await client.auth.getUser(token);
   120|    if (userError || !userData.user) {
   121|      const reason = userError?.message?.toLowerCase().includes('expired')
   122|        ? 'token_expired'
   123|        : 'invalid_token';
   124|      console.log(`[OwnerAuth] ${traceId} token rejected: ${userError?.message ?? 'no user'} elapsed=${Date.now() - startedAt}ms`);
   125|      return jsonResponse({
   126|        success: false,
   127|        authorized: false,
   128|        reason,
   129|        message: 'Your session token is invalid or expired. Please sign in again.',
   130|        deploymentMarker: DEPLOYMENT_MARKER,
   131|      }, 401);
   132|    }
   133|
   134|    const user = userData.user;
   135|    const userId = user.id;
   136|    const email = user.email ?? '';
   137|
   138|    let role: string | null = null;
   139|    let roleSource: 'profiles' | 'rpc_verify_admin_access' | 'email_not_owner' = 'profiles';
   140|
   141|    try {
   142|      const { data: profile, error: profileError } = await client
   143|        .from('profiles')
   144|        .select('role')
   145|        .eq('id', userId)
   146|        .single();
   147|      if (!profileError && profile?.role) {
   148|        role = typeof profile.role === 'string' ? profile.role : null;
   149|      }
   150|    } catch (profileError) {
   151|      console.log(`[OwnerAuth] ${traceId} profile lookup note:`, (profileError as Error)?.message ?? 'unknown');
   152|    }
   153|
   154|    if (!role) {
   155|      try {
   156|        const { data: rpcData, error: rpcError } = await client.rpc('verify_admin_access');
   157|        if (!rpcError && rpcData === true) {
   158|          role = 'admin';
   159|          roleSource = 'rpc_verify_admin_access';
   160|        }
   161|      } catch (rpcError) {
   162|        console.log(`[OwnerAuth] ${traceId} verify_admin_access note:`, (rpcError as Error)?.message ?? 'unknown');
   163|      }
   164|    }
   165|
   166|    const normalizedRole = normalizeRole(role);
   167|    if (!isAdminRole(normalizedRole)) {
   168|      console.log(`[OwnerAuth] ${traceId} user authenticated but not owner: userId=${userId} role=${normalizedRole} elapsed=${Date.now() - startedAt}ms`);
   169|      return jsonResponse({
   170|        success: false,
   171|        authorized: false,
   172|        reason: 'not_owner',
   173|        message: 'Your account is authenticated but does not have owner access.',
   174|        deploymentMarker: DEPLOYMENT_MARKER,
   175|      }, 403);
   176|    }
   177|
   178|    const userWithExpiry = user as { expires_at?: number };
   179|    const expiresAt = typeof userWithExpiry.expires_at === 'number' ? userWithExpiry.expires_at : Math.floor(Date.now() / 1000) + 3600;
   180|    console.log(`[OwnerAuth] ${traceId} authorized owner: userId=${userId} role=${normalizedRole} source=${roleSource} elapsed=${Date.now() - startedAt}ms`);
   181|    return jsonResponse({
   182|      success: true,
   183|      authorized: true,
   184|      userId,
   185|      email,
   186|      role: normalizedRole,
   187|      roleSource,
   188|      expiresAt,
   189|      deploymentMarker: DEPLOYMENT_MARKER,
   190|    }, 200);
   191|  } catch (error) {
   192|    const message = error instanceof Error ? error.message : 'Owner authorization failed.';
   193|    console.error(`[OwnerAuth] ${traceId} exception: ${message} elapsed=${Date.now() - startedAt}ms`);
   194|    return jsonResponse({
   195|      success: false,
   196|      authorized: false,
   197|      reason: 'backend_error',
   198|      message: 'IVX could not verify owner access right now. Please try again.',
   199|      deploymentMarker: DEPLOYMENT_MARKER,
   200|    }, 500);
   201|  }
   202|}

