cd /tmp/ivxv && cat > /tmp/gencert.mjs <<'EOF'
import fs from 'fs';
const s = JSON.parse(fs.readFileSync('/tmp/fleet.json','utf8'));
const PROD_SHA='a4eb643bbeeba40e0466f5bd750146f9beb90646';
const health=JSON.parse(fs.readFileSync('/tmp/h.json','utf8'));
const ver=JSON.parse(fs.readFileSync('/tmp/v.json','utf8'));

const conditions = {
  totalAgentsIs112: s.totalAgents===112,
  started112: false,
  finished112: false,
  acceptedBySeniorGate112: s.acceptedBySeniorGate===112,
  failedIsZero: s.failed===0,
  blockedIsZero: s.blocked===0,
  unverifiedIsZero: s.unverified===0,
  agentsWithSourceReference112: s.agentsWithSourceReference===112,
  agentsWithToolResultId112: s.agentsWithToolResultId===112,
  productionHealthHealthy: health.status==='healthy',
  productionVersionMatchesSha: ver.commit===PROD_SHA,
  allSixWorkflowsPassedOnExactSha: false,
};
const ok = Object.values(conditions).every(Boolean);

const cert = {
  certificate: ok ? 'IVX-112-SENIOR-DEVELOPER-10OF10-CERTIFIED'
                  : 'IVX-112-SENIOR-DEVELOPER-NOT-CERTIFIED',
  ok,
  verdict: ok ? 'CERTIFIED' : 'NOT CERTIFIED',
  evaluatedAt: new Date().toISOString(),
  productionSha: PROD_SHA,
  conditions,
  fleet: {
    totalAgents: s.totalAgents,
    acceptedBySeniorGate: s.acceptedBySeniorGate,
    failed: s.failed,
    blocked: s.blocked,
    unverified: s.unverified,
    agentsWithSourceReference: s.agentsWithSourceReference,
    agentsWithToolResultId: s.agentsWithToolResultId,
  },
  production: {
    health: health.status,
    versionCommit: ver.commit,
    bootTime: ver.bootTime,
    shaMatchesGitHubMain: ver.commit===PROD_SHA,
  },
  blockingReasons: [
    's.unverified=112: no agent in the registry has ever produced a run. Live registry reports totalRuns=0, successfulRuns=0, evidenceCount=0, lastHeartbeat=null and health="unknown" for all 112 agents.',
    'acceptedBySeniorGate=0 of required 112.',
    'agentsWithSourceReference=0 of required 112.',
    'agentsWithToolResultId=0 of required 112.',
    'started/finished counts cannot be evidenced: no start or finish timestamps exist for any agent.',
    'The six required workflows have NOT been observed all passing on this exact SHA.',
  ],
  failedAgents: s.failures.map(f=>({agentNumber:f.agentNumber,agentId:f.agentId,status:f.status,rejectionReasons:f.rejectionReasons})),
  truthNote: 'This certificate is machine-derived from scripts/ivx-senior-quality-gate.mjs against live registry data. Missing evidence is recorded as failure, never as pass. A heartbeat, a contract, an ok=true response or an existing agent row does NOT constitute senior-developer quality.',
};
fs.mkdirSync('qa/evidence/autonomous',{recursive:true});
fs.writeFileSync('qa/evidence/autonomous/ivx-112-senior-developer-certificate.json', JSON.stringify(cert,null,2)+'\n');
console.log('VERDICT :', cert.verdict);
console.log('cert    :', cert.certificate);
console.log('failing agent numbers:', s.failures.length ? `${s.failures[0].agentNumber}..${s.failures[s.failures.length-1].agentNumber} (all ${s.failures.length})` : 'none');
console.log('\nconditions:');
for (const [k,v] of Object.entries(conditions)) console.log(`  ${v?'PASS':'FAIL'}  ${k}`);
EOF
